/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Form that lists all ALM Supplier Volumetric Rebates and allows to
/// maintain them
/// </summary>
[Form]
public class METALMSupplierVolumetricRebateForm extends FormRun
{

}

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Allows edits to the ALM Supplier Volumetric Rebate according to its
    /// status
    /// </summary>
    public void allowEditALMSupplierVolumetricRebate()
    {
        boolean editable;

        editable = (METALMSupplierVolumetricRebateHeader.Status != METALMSupplierVolumetricRebateStatus::Processed);
            
        GridTabPage.allowEdit(editable);
        DetailsTabPage.allowEdit(editable);
        CVLinesActionStrip.enabled(editable);
        METALMSupplierVolumetricRebateProcessAction.enabled(editable);

    }

    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// Set mandatory fields in the lines according  to the ALM SVR type and line type
    /// </summary>
    public void manageAlmSvrEditableLineFields()
    {
        boolean isSVR, isCust;

        isSVR   = METALMSupplierVolumetricRebateLine.header().Type == METALMSupplierVolumetricRebateType::SVR;
        isCust  = METALMSupplierVolumetricRebateLine.CustVend == CustVendACType::Cust;

        if(METALMSupplierVolumetricRebateLine.header().CustLegalEntity == curExt())
        {
            METALMSupplierVolumetricRebateLine_ds.object(fieldNum(METALMSupplierVolumetricRebateLine, LedgerDimension))
                .allowEdit(isSVR || isCust);
            METALMSupplierVolumetricRebateLine_ds.object(fieldNum(METALMSupplierVolumetricRebateLine, FinancialDimension))
                .allowEdit(true);
            CVRebateLineFinancialDimensionsTabPage.allowEdit(true);
        }
        else
        {
            METALMSupplierVolumetricRebateLine_ds.object(fieldNum(METALMSupplierVolumetricRebateLine, LedgerDimension))
                .allowEdit(isSVR && !isCust);
            METALMSupplierVolumetricRebateLine_ds.object(fieldNum(METALMSupplierVolumetricRebateLine, FinancialDimension))
                .allowEdit(!isCust);
            CVRebateLineFinancialDimensionsTabPage.allowEdit(!isCust);
        }
        METALMSupplierVolumetricRebateLine_ds.object(fieldNum(METALMSupplierVolumetricRebateLine, ProcurementCategory))
                .allowEdit(!(isSVR || isCust));
    }

/// <summary>
/// MPJ-5904, GVivanco, 20Jul2021
/// Create method for METALMSupplierVolumetricRebateHeader data source.
/// </summary>
/// <param name = "_append">boolean variable</param>
public void create(boolean _append = false)
{
    super(_append);
    element.allowEditALMSupplierVolumetricRebate();
    HeaderViewTabPage.activatePage();
}

/// <summary>
/// Customer legal entity modified method
/// </summary>
public void modified()
{
    METALMSupplierVolumetricRebateHeader.CustomerAccount = '';
    super();
}

/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Inits the METALMSupplierVolumetricRebateLine with values
/// from METALMSupplierVolumetricRebateHeader
/// </summary>
public void initValue()
{
    super();
    METALMSupplierVolumetricRebateLine.initFromALMSupplierVolumetricRebateHeader(METALMSupplierVolumetricRebateHeader);
}

        /// <summary>
        /// MPJ-5904, GVivanco, 02Jul2021
        /// Active method for METALMSupplierVolumetricRebateLine data source
        /// in METALMSupplierVolumetricRebateForm
        /// </summary>
        /// <returns>An int value</returns>
        public int active()
        {
            int ret;

            ret = super();

            element.allowEditALMSupplierVolumetricRebate();
            element.manageAlmSvrEditableLineFields();

            return ret;
        }

            /// <summary>
            /// MPJ-5904, GVivanco, 26Jun2021
            /// Modified method for CustVend field of METALMSupplierVolumetricRebateLine data source
            /// </summary>
            public void modified()
            {
                super();

                element.manageAlmSvrEditableLineFields();
            }

/// <summary>
/// MPJ-5904, GVivanco, 02July2021
/// LookupReference method for Procurement Categories
/// </summary>
/// <param name = "_formReferenceControl">Procurement Category control</param>
/// <returns>The selected record for record mode selection; otherwise null.</returns>
public Common lookupReference(FormReferenceControl _formReferenceControl)
{
    return EcoResCategory::lookupCategoryHierarchyRole(_formReferenceControl, EcoResCategoryNamedHierarchyRole::Procurement);
}

/// <summary>
/// MPJ-5904, GVivanco, 02July2021
/// resolveReference method for Procurement Categories
/// </summary>
/// <param name = "_formReferenceControl">Procurement Category control</param>
/// <returns>The selected record for record mode selection; otherwise null.</returns>
public Common resolveReference(FormReferenceControl _formReferenceControl)
{
    return EcoResCategory::resolveCategoryHierarchyRole(_formReferenceControl, EcoResCategoryNamedHierarchyRole::Procurement);
}

        /// <summary>
        /// CustFreeTextInvoice clicked method
        /// </summary>
        public void clicked()
        {
            if(METALMSupplierVolumetricRebateHeader.CustLegalEntity)
            {
                changecompany(METALMSupplierVolumetricRebateHeader.CustLegalEntity)
                {
                    Args args = new Args();

                    args.record(METALMSupplierVolumetricRebateHeader);

                    args.caller(this);

                    new MenuFunction(menuItemDisplayStr(CustFreeInvoice), MenuItemType::Display).run(args);
                }
            }
        }

        /// <summary>
        /// Customer account lookup method
        /// </summary>
        public void lookup()
        {
            Query				 query = new Query();
            QueryBuildDataSource qbdsCustTable, qbdsDirParty;
            SysTableLookup	     sysTableLookup;
            FormRun              formRun        = this.formRun();
            FormControl          purposeCtrl    = formRun.design().controlName(formControlStr(METALMSupplierVolumetricRebateForm, CVHeader_CustLegalEntity));
        
            if (purposeCtrl.valueStr() != "")
            {
                sysTableLookup = SysTableLookup::newParameters(tableNum(CustTable), this,true);
                sysTableLookup.parmUseLookupValue(false);
                sysTableLookup.addLookupfield(fieldNum(CustTable, AccountNum));
                sysTableLookup.addLookupfield(fieldNum(CustTable, party), false);
                sysTableLookup.setLabel("@SYS177436");

                qbdsCustTable = query.addDataSource(tableNum(CustTable));
                qbdsCustTable.company(purposeCtrl.valueStr());

                qbdsDirParty = qbdsCustTable.addDataSource(tableNum(DirPartyTable));
                qbdsDirParty.company(purposeCtrl.valueStr());
                qbdsDirParty.joinMode(JoinMode::InnerJoin);
                qbdsDirParty.addLink(fieldNum(CustTable,Party),fieldNum(DirPartyTable,RecId));

                sysTableLookup.parmQuery(query);
                sysTableLookup.performFormLookup();
            }
            else
            {
                throw warning("@MET:CustAccNumLEValidation");
            }
        }

